package com.example.department.dto;
public class DepartmentResponseDto { private Long departmentId; private String departmentName; private String description; public DepartmentResponseDto(){} public DepartmentResponseDto(Long id,String n,String d){departmentId=id;departmentName=n;description=d;} public Long getDepartmentId(){return departmentId;} public void setDepartmentId(Long v){departmentId=v;} public String getDepartmentName(){return departmentName;} public void setDepartmentName(String v){departmentName=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} }
